case class Version(major: Int, minor: Int) extends Ordered[Version] {
  def compare(that: Version): Int =
    if (major != that.major) major - that.major else minor - that.minor
}

Version(1, 2) < Version(1, 10)   // true - <, <=, >, >= come from Ordered

